import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"D0.1 · Product wedge and real-task baseline","description":"Hearth D0.1 development increment: A clear product statement, at least 12 verifiable tasks, and baselines for both fully manual work and direct Codex use.","frontmatter":{"title":"D0.1 · Product wedge and real-task baseline","description":"Hearth D0.1 development increment: A clear product statement, at least 12 verifiable tasks, and baselines for both fully manual work and direct Codex use.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-0/d0-1.md","filePath":"en/delivery/stage-0/d0-1.md","lastUpdated":1793797632000}'),r={name:"en/delivery/stage-0/d0-1.md"};function n(o,e,l,d,c,h){return t(),s("div",null,[...e[0]||(e[0]=[i(`<p class="eyebrow">STAGE 0 · D0.1 · 1 / 4</p><h1 id="d0-1-·-product-wedge-and-real-task-baseline" tabindex="-1">D0.1 · Product wedge and real-task baseline <a class="header-anchor" href="#d0-1-·-product-wedge-and-real-task-baseline" aria-label="Permalink to &quot;D0.1 · Product wedge and real-task baseline&quot;">​</a></h1><p class="lead">Fix who uses Hearth, in which scenario, and why, together with a verifiable set of real tasks; the prototype, contracts, and evaluation all depend on it.</p><p class="page-meta">STAGE 0 · D0.1 · 1 vertical increment · 4 work packages</p><div class="section-grid"><div><strong>User-visible outcome</strong>A clear product statement, at least 12 verifiable tasks, and baselines for both fully manual work and direct Codex use.</div><div><strong>Completion gate</strong>At least 12 tasks have explicit inputs, artifacts, and acceptance; Hearth&#39;s independent value is clear; the set includes success, failure, approval waits, and takeover.</div></div><h2 id="what-this-increment-solves" tabindex="-1">What this increment solves <a class="header-anchor" href="#what-this-increment-solves" aria-label="Permalink to &quot;What this increment solves&quot;">​</a></h2><p>A clear product statement, at least 12 verifiable tasks, and baselines for both fully manual work and direct Codex use.</p><p>Stage 0 produces product truth and implementation contracts. Without real tasks, a clickable prototype, and repeatable evaluation, later work mistakes assumptions for facts.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li>An empty repository, a recordable set of real work samples, and one first user willing to keep giving feedback.</li><li>Baselines for fully manual work and direct Codex use are observable before the system exists.</li><li>This stage does not connect real sending, payment, deletion, or system-setting changes.</li></ul><h2 id="four-implementation-work-packages" tabindex="-1">Four implementation work packages <a class="header-anchor" href="#four-implementation-work-packages" aria-label="Permalink to &quot;Four implementation work packages&quot;">​</a></h2><blockquote><p>Every work package must produce runnable code, a reproducible check, or a concrete UI result; interfaces alone or pages alone do not count as complete.</p></blockquote><h3 id="_01-·-first-user-and-task-wedge" tabindex="-1">01 · First user and task wedge <a class="header-anchor" href="#_01-·-first-user-and-task-wedge" aria-label="Permalink to &quot;01 · First user and task wedge&quot;">​</a></h3><p>Choose one real user and one high-frequency task family. Record current alternatives, weekly frequency, manual minutes, error-prone steps, and acceptable external risk. Independent research reporting is a valid example only when real work records substantiate it.</p><h3 id="_02-·-real-task-evidence-pack" tabindex="-1">02 · Real-task evidence pack <a class="header-anchor" href="#_02-·-real-task-evidence-pack" aria-label="Permalink to &quot;02 · Real-task evidence pack&quot;">​</a></h3><p>Create fixtures/tasks with fixed inputs, expected artifacts, acceptance rules, failure samples, risk level, and task family. Keep at least 12 of 20–30 candidates and cover the major families: research, documents, code, email, calendar, web, data, and desktop.</p><h3 id="_03-·-dual-baseline-experiment" tabindex="-1">03 · Dual-baseline experiment <a class="header-anchor" href="#_03-·-dual-baseline-experiment" aria-label="Permalink to &quot;03 · Dual-baseline experiment&quot;">​</a></h3><p>Run the same tasks manually and with direct Codex. Capture manual minutes, success rate, Token/cost, failure classes, rework, and user complaints with the same validator; never compare different tasks or standards.</p><h3 id="_04-·-value-and-stop-decision" tabindex="-1">04 · Value and stop decision <a class="header-anchor" href="#_04-·-value-and-stop-decision" aria-label="Permalink to &quot;04 · Value and stop decision&quot;">​</a></h3><p>Write a one-page product definition stating what Hearth adds beyond direct Codex: durable state, approvals, recovery, audit, artifact validation, or long-term context. Record non-goals, success metrics, and kill criteria so more features cannot substitute for real value.</p><h2 id="engineering-map" tabindex="-1">Engineering map <a class="header-anchor" href="#engineering-map" aria-label="Permalink to &quot;Engineering map&quot;">​</a></h2><h3 id="primary-directories-and-modules" tabindex="-1">Primary directories and modules <a class="header-anchor" href="#primary-directories-and-modules" aria-label="Permalink to &quot;Primary directories and modules&quot;">​</a></h3><ul><li><code>packages/core/src/schema</code> — domain entities, state machines, and failure taxonomy</li><li><code>packages/eventlog</code> — event log, projections, and migrations</li><li><code>packages/evals</code> — task set, runner, scoring, and manual review</li><li><code>apps/web</code> — Today, Needs you, Artifacts, Settings, and task-detail prototype</li><li><code>fixtures/tasks</code> — real task samples and failure samples</li><li><code>docs/adr</code> — build-vs-integrate, event model, and frontend projection decisions</li></ul><h3 id="key-interfaces" tabindex="-1">Key interfaces <a class="header-anchor" href="#key-interfaces" aria-label="Permalink to &quot;Key interfaces&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Contract that must hold</th></tr></thead><tbody><tr><td><code>Event</code></td><td>id, type, schemaVersion, occurredAt, actor, subject, causationId, correlationId, payload; append-only with immutable history.</td></tr><tr><td><code>TaskCardProjection</code></td><td>taskId, title, state, primaryAction, reason, lastEventAt, artifacts, budget; the page never reads database columns.</td></tr><tr><td><code>ExecutorEvent</code></td><td>normalized event, artifact reference, structResult, validation, failureClass, recoverable; executors never write the primary database.</td></tr><tr><td><code>Approval</code></td><td>effectPreview, scope, expiresAt, decision, idempotencyKey; approval binds to the real action and parameters.</td></tr></tbody></table><h3 id="shared-verification-commands" tabindex="-1">Shared verification commands <a class="header-anchor" href="#shared-verification-commands" aria-label="Permalink to &quot;Shared verification commands&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:contract</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eval:smoke:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rerun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 12</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scores</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inspect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> and</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 390px</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mobile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prototypes</span></span></code></pre></div><h2 id="acceptance-rehearsal" tabindex="-1">Acceptance rehearsal <a class="header-anchor" href="#acceptance-rehearsal" aria-label="Permalink to &quot;Acceptance rehearsal&quot;">​</a></h2><ol><li>Start hearthd from a clean data directory, open the <a href="/hearth-os/en/delivery/stage-0/d0-1.html">D0.1 page</a>, and confirm it relies on no browser cache or hand-seeded data.</li><li>Complete the four work packages in order: First user and task wedge; Real-task evidence pack; Dual-baseline experiment; Value and stop decision. Preserve the matching test output, screenshot, or artifact version after each package.</li><li>Reproduce the failure case &quot;A prototype state cannot be mapped&quot;. The page must show &quot;The page shows Needs attention and records the unknown projection field and task ID.&quot;, then recover with &quot;Add the mapping, update contract tests, and replay the original path.&quot;; no duplicate effect or unregistered state is allowed.</li><li>Restart the service and reopen the task. Runtime state, approvals, artifacts, and recovery entry points must all come from durable projections rather than the current page.</li><li>Run the shared verification commands above and export the evidence. The completion gate is: At least 12 tasks have explicit inputs, artifacts, and acceptance; Hearth&#39;s independent value is clear; the set includes success, failure, approval waits, and takeover.</li></ol><h2 id="deliverables" tabindex="-1">Deliverables <a class="header-anchor" href="#deliverables" aria-label="Permalink to &quot;Deliverables&quot;">​</a></h2><ul><li>Product statement and task wedge</li><li>12+ real task-card samples</li><li>Manual/Codex baseline table</li><li>Non-goals, risks, and success metrics</li></ul><h2 id="completion-decision" tabindex="-1">Completion decision <a class="header-anchor" href="#completion-decision" aria-label="Permalink to &quot;Completion decision&quot;">​</a></h2><ul><li>[ ] At least 12 tasks have explicit inputs, artifacts, and acceptance; Hearth&#39;s independent value is clear; the set includes success, failure, approval waits, and takeover.</li><li>[ ] Deliverables match the contracts and task-card projection with no unregistered field or state.</li><li>[ ] At least one failure path has an actionable recovery, and key actions leave audit events.</li><li>[ ] The demo needs no manual database edit, terminal-only stitching, or permanent mock.</li></ul><h2 id="failure-and-recovery" tabindex="-1">Failure and recovery <a class="header-anchor" href="#failure-and-recovery" aria-label="Permalink to &quot;Failure and recovery&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Case</th><th>User sees</th><th>Recovery</th></tr></thead><tbody><tr><td>A prototype state cannot be mapped</td><td>The page shows Needs attention and records the unknown projection field and task ID.</td><td>Add the mapping, update contract tests, and replay the original path.</td></tr><tr><td>A real task cannot be accepted</td><td>The task stays in the candidate pool with a reason; it never becomes a build commitment.</td><td>Clarify inputs, artifacts, or acceptance, or replace the task.</td></tr><tr><td>Baselines are not comparable</td><td>The task stays out of the evaluation set so distorted data cannot prove value.</td><td>Recapture manual minutes, success rate, Token usage, and failure type.</td></tr></tbody></table><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><ul><li>Do not build a complete kernel before the interface.</li><li>Do not substitute document completion for a clickable prototype and repeatable evaluation.</li><li>Do not connect real high-risk external side effects.</li></ul><h2 id="source-material-and-next-step" tabindex="-1">Source material and next step <a class="header-anchor" href="#source-material-and-next-step" aria-label="Permalink to &quot;Source material and next step&quot;">​</a></h2><h3 id="source-material" tabindex="-1">Source material <a class="header-anchor" href="#source-material" aria-label="Permalink to &quot;Source material&quot;">​</a></h3><ul><li><a href="/hearth-os/en/design/">Design and tradeoffs</a></li><li><a href="/hearth-os/en/reference/checklists.html">Default checklists</a></li><li><a href="/hearth-os/en/architecture/domain-model.html">Domain model and protocol</a></li><li><a href="/hearth-os/en/architecture/evaluation.html">Evaluation</a></li></ul><h3 id="next-step" tabindex="-1">Next step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next step&quot;">​</a></h3><p>Continue to <a href="/hearth-os/en/delivery/stage-0/d0-2.html">D0.2 · Clickable end-to-end product prototype</a>. Finish this increment&#39;s acceptance first; do not hide gaps with later work.</p>`,42)])])}const k=a(r,[["render",n]]);export{u as __pageData,k as default};
